 right:{label:'MainActivity.kt',era:'Modern',lang:'kotlin',code:'fun showLoading(loading: Boolean) {\n    binding.progressBar.isVisible = loading\n    binding.btnGetLocation.isEnabled = !loading\n}\n\nshowLoading(true)    // before the slow work\nshowLoading(false)   // when it finishes'},
